// Measured per-pitch calibration, Q3.13, MIDI48..91; unity elsewhere.
// Coefficients generated by tests/calibration_20261018/calibrate.py.
// Keep the old coefficient throughout stealing; commit only when the new load completes.
module piano_note_gain #(parameter SAMPLE_W=24)(
    input wire clk, input wire rst_n,
    input wire start, input wire [6:0] note_in, input wire load_done,
    input wire signed [SAMPLE_W-1:0] sample_in,
    output wire signed [SAMPLE_W-1:0] sample_out
);
function [15:0] gain_for_note;
    input [6:0] note;
    begin
        case(note)
            7'd48: gain_for_note = 16'd7190;
            7'd49: gain_for_note = 16'd7801;
            7'd50: gain_for_note = 16'd8313;
            7'd51: gain_for_note = 16'd8581;
            7'd52: gain_for_note = 16'd8525;
            7'd53: gain_for_note = 16'd9620;
            7'd54: gain_for_note = 16'd10486;
            7'd55: gain_for_note = 16'd11155;
            7'd56: gain_for_note = 16'd11704;
            7'd57: gain_for_note = 16'd11548;
            7'd58: gain_for_note = 16'd10813;
            7'd59: gain_for_note = 16'd8955;
            7'd60: gain_for_note = 16'd6106;
            7'd61: gain_for_note = 16'd8229;
            7'd62: gain_for_note = 16'd10937;
            7'd63: gain_for_note = 16'd13997;
            7'd64: gain_for_note = 16'd17062;
            7'd65: gain_for_note = 16'd12468;
            7'd66: gain_for_note = 16'd8556;
            7'd67: gain_for_note = 16'd5694;
            7'd68: gain_for_note = 16'd3739;
            7'd69: gain_for_note = 16'd3904;
            7'd70: gain_for_note = 16'd4040;
            7'd71: gain_for_note = 16'd4165;
            7'd72: gain_for_note = 16'd4268;
            7'd73: gain_for_note = 16'd4711;
            7'd74: gain_for_note = 16'd5159;
            7'd75: gain_for_note = 16'd5616;
            7'd76: gain_for_note = 16'd6068;
            7'd77: gain_for_note = 16'd8137;
            7'd78: gain_for_note = 16'd10462;
            7'd79: gain_for_note = 16'd12633;
            7'd80: gain_for_note = 16'd13475;
            7'd81: gain_for_note = 16'd19690;
            7'd82: gain_for_note = 16'd28457;
            7'd83: gain_for_note = 16'd31974;
            7'd84: gain_for_note = 16'd32768;
            7'd85: gain_for_note = 16'd28450;
            7'd86: gain_for_note = 16'd22520;
            7'd87: gain_for_note = 16'd17670;
            7'd88: gain_for_note = 16'd13845;
            7'd89: gain_for_note = 16'd16849;
            7'd90: gain_for_note = 16'd20286;
            7'd91: gain_for_note = 16'd24350;
            default: gain_for_note = 16'd8192;
        endcase
    end
endfunction
reg [15:0] pending_gain, active_gain;
always @(posedge clk or negedge rst_n)
    if (!rst_n) begin pending_gain<=16'd8192;active_gain<=16'd8192;end
    else begin
        if (start) pending_gain<=gain_for_note(note_in);
        if (load_done) active_gain<=pending_gain;
    end
wire signed [16:0] positive_gain=$signed({1'b0,active_gain});
wire signed [SAMPLE_W+16:0] product=sample_in * positive_gain;
wire signed [SAMPLE_W+16:0] scaled=product >>> 13;
localparam signed [SAMPLE_W-1:0] MAX_SAMPLE={1'b0,{(SAMPLE_W-1){1'b1}}};
localparam signed [SAMPLE_W-1:0] MIN_SAMPLE={1'b1,{(SAMPLE_W-1){1'b0}}};
assign sample_out=(scaled > MAX_SAMPLE) ? MAX_SAMPLE :
                  (scaled < MIN_SAMPLE) ? MIN_SAMPLE : scaled[SAMPLE_W-1:0];
endmodule
